mapper.select:
SELECT s.StudentId, s.StudentCode, s.FullName, s.Gender, s.DateOfBirth, s.ClassId, c.ClassName, s.Hometown, s.ParentName, s.ParentPhone, s.BoardingStatus, s.UserId, s.CreatedAt, s.UpdatedAt FROM Students s INNER JOIN Classes c ON s.ClassId = c.ClassId
AND ( s.StudentCode LIKE '%' + #{keyword} + '%' OR s.FullName LIKE N'%' + #{keyword} + '%' )
AND s.ClassId = #{classId}
AND s.BoardingStatus = #{boardingStatus}
ORDER BY s.StudentId DESC

SELECT COUNT(1)
FROM Students
WHERE StudentCode = #{studentCode}


    AND StudentId != #{studentId}

SELECT COUNT(*)
FROM Students
WHERE BoardingStatus = #{status}
